const $=s=>document.querySelector(s), escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const [manual,rubric]=await Promise.all(['playbook','rubric'].map(f=>fetch(`/data/${f}.json`).then(r=>r.json())));
const key='dokiplayer-barovia-workflow-v2';
let session;
try{session=JSON.parse(localStorage.getItem(key)||'null');}catch{}
const newRequested=new URLSearchParams(location.search).has('newSession');
if(session&&(newRequested)){const archive=JSON.parse(localStorage.getItem('dokiplayer-session-archive')||'[]');archive.push(session);localStorage.setItem('dokiplayer-session-archive',JSON.stringify(archive));session=null;}
if(newRequested)history.replaceState(null,'',location.pathname);
if(!session)session={id:crypto.randomUUID(),name:'雾锁巴罗维亚',mode:'fresh_game_required',source:'workbench',manualVersion:manual.manualVersion,engineVersion:null,engineBuild:null,scriptVersion:null,createdAt:new Date().toISOString(),gameStartedAt:null,completedSteps:0,events:[],newGameVerified:false};
function persist(){localStorage.setItem(key,JSON.stringify(session));$('#script-version-display').textContent=session.scriptVersion||'待核验';$('#engine-version-display').textContent=session.engineVersion||'待核验';$('#save-state').textContent='已保存到当前浏览器';}
function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,5000);}
function versions(){for(const [id,k]of [['engine-version','engineVersion'],['engine-build','engineBuild'],['script-version','scriptVersion']])session[k]=$(id[0]==='#'?id:`#${id}`).value.trim()||null;}
for(const [id,k]of [['engine-version','engineVersion'],['engine-build','engineBuild'],['script-version','scriptVersion']]){$(`#${id}`).value=session[k]||'';$(`#${id}`).onchange=()=>{versions();persist();};}
$('#manual-version').textContent=`v${session.manualVersion}`;
$('#version-baseline').textContent=`手册已观察兼容基线：引擎 ${manual.compatibility.engineVersion} / ${manual.compatibility.engineBuild}，本故事 ${manual.compatibility.stories.find(s=>s.id==='barovia').scriptVersion}。请核验本次实际版本，不能直接沿用。`;
$('#rubric-list').innerHTML=rubric.dimensions.map(d=>`<p><strong>${escape(d.name)}</strong> · 0–100<br>${escape(d.description)}</p>`).join('');
function render(){const index=Math.min(session.completedSteps,manual.steps.length-1),step=manual.steps[index];$('#workflow').innerHTML=manual.steps.map((s,i)=>`<li class="${i<session.completedSteps?'done':i===index?'current':''}">${escape(s.title)}</li>`).join('');$('#current-step-label').textContent=`步骤 ${index+1}/${manual.steps.length}`;$('#current-step-title').textContent=step.title;$('#current-instruction').textContent=step.instruction;$('#event-count').textContent=session.events.length;$('#new-game-confirm').checked=session.newGameVerified;$('#event-list').innerHTML=session.events.slice().reverse().map(e=>`<article class="event-entry"><strong>${escape(e.kind)} · ${escape(e.stage)}</strong><p>${escape(e.action)}</p><p>实际：${escape(e.result)}</p><small>${escape(new Date(e.at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}))}</small></article>`).join('')||'<p>尚无操作记录。</p>';}
function record(kind,advance=false){versions();const step=manual.steps[Math.min(session.completedSteps,manual.steps.length-1)];const action=$('#action-note').value.trim(),result=$('#result-note').value.trim();if(!action||!result)return notify('请填写实际操作与页面反馈，不能空记录。');if(advance&&step.id==='baseline'&&!$('#new-game-confirm').checked)return notify('正式评测须先核验新游戏起点。');session.events.push({id:crypto.randomUUID(),at:new Date().toISOString(),stage:step.title,kind,action,result,manualVersion:session.manualVersion,engineVersion:session.engineVersion,engineBuild:session.engineBuild,scriptVersion:session.scriptVersion});if(step.id==='baseline'&&advance){session.newGameVerified=true;session.gameStartedAt=new Date().toISOString();}if(advance)session.completedSteps=Math.min(manual.steps.length-1,session.completedSteps+1);$('#action-note').value='';$('#result-note').value='';persist();render();notify(kind==='卡点'?'卡点已记录，流程保持当前阶段':'本步已记录');}
$('#restart-session').onclick=()=>{location.href=location.pathname+'?newSession=1';};
$('#complete-step').onclick=()=>record('流程确认',true);$('#record-only').onclick=()=>record('操作记录');$('#record-blocker').onclick=()=>record('卡点');
$('#connect-game').onclick=()=>{const frame=$('#game-frame');if(!frame.src){frame.src='https://test.aimeng.ai/scripts/creator_d72affd9165148d68a2eee480b42f13b';frame.hidden=false;$('#game-placeholder').hidden=true;session.events.push({id:crypto.randomUUID(),at:new Date().toISOString(),stage:'工作台入口',kind:'入口操作',action:'在工作台下方载入雾锁巴罗维亚主菜单',result:'已发起载入；页面能否显示与登录状态需现场核验',manualVersion:session.manualVersion});persist();render();}$('#connect-game').textContent='已发起载入';};
$('#show-instructions').onclick=()=>$('#embed-help').hidden=!$('#embed-help').hidden;
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
$('#download-session').onclick=()=>{versions();persist();download(`DokiPlayer-${session.id}.json`,JSON.stringify({...session,exportedAt:new Date().toISOString()},null,2),'application/json');};
$('#download-markdown').onclick=()=>{versions();const lines=[`# ${session.name} · 工作台流程记录`,'',`引擎：${session.engineVersion||'未确认'} / ${session.engineBuild||'未确认'}`,`剧本：${session.scriptVersion||'未确认'}`,`手册：${session.manualVersion}`,`新游戏起点已核验：${session.newGameVerified?'是':'否'}`,`会话开始：${session.createdAt}`,`导出：${new Date().toISOString()}`,'','会话用时包含准备、讨论与等待，不等于纯游玩时长。','',...session.events.flatMap(e=>[`## ${e.stage} · ${e.kind}`,e.at,'',e.action,'',`实际反馈：${e.result}`,''])];download(`DokiPlayer-${session.id}.md`,lines.join('\n'),'text/markdown');};
setInterval(()=>{const n=Math.max(0,Math.floor((Date.now()-Date.parse(session.createdAt))/1000));$('#session-time').textContent=`${Math.floor(n/60).toString().padStart(2,'0')}:${(n%60).toString().padStart(2,'0')}`;},1000);render();persist();
